/*
  Add the two Turkish case folds manually. Normally doing this would cause the Turkish I (I without dot) to override the English I and case fold incorrectly if the text is not Turkish (ı [Turkish i without dot] instead of i [English lowercase i]). There's no way to have the two in the same table, so we're going to fudge this problem and always make the I case fold to i and add an entry for ı that case folds to i as well
*/
FOLDING_MAP.set(304, [105]); // İ to i
FOLDING_MAP.set(305, [105]); // ı to i

/**
 * Normalize a string using the compatibility normalization method in order to compare
 * two strings together.
 * Reference
 *  - https://www.w3.org/TR/charmod-norm/#CompatibilityFoldNormalizationStep
 *
 * @method caseFoldUnicode
 * @memberof axe.commons.text
 * @instance
 * @param {string} input - The string to case fold
 * @returns {string} The case-folded string
 */
export default function caseFoldUnicode(input) {
  // ie11 support, just fold the case once
  if (!('normalize' in String.prototype)) {
    return caseFold(input).toLowerCase();
  }

  // even though the algorithm calls for normalizing to NFD, that breaks case folding
  // in that İ would be normalized to the two separate unicode points, I and the dot,
  // which would not be case folding correctly into just i, but instead would be case
  // folded as ı (Turkish dotless letter i) and the dot. to fix that we should
  // normalize to NFC which keeps the İ as a single unicode character which would then
  // casefold to i properly. The example that https://www.w3.org/TR/charmod-norm/#PreNormalization
  // describes in example 23 is still fixed by normalizing to NFC instead of NFD
  return caseFold(
    caseFold(input.normalize('NFC')).normalize('NFKD')
  ).toLowerCase();
}

/**
 * Applies Unicode case folding to a string without having to know the strings locale.
 * We could have used toLocaleLowerCase(locale) to do this, but we can't always guarantee
 * that we'll know the strings locale.
 * @param {string} input - The string to case fold
 * @returns {string} The case-folded string
 */
export function caseFold(input) {
  let result = '';

  for (const char of input) {
    const codePoint = char.codePointAt(0);
    const mapping = FOLDING_MAP.get(codePoint);
    result += mapping ? String.fromCodePoint(...mapping) : char;
  }

  return result;
}
